/** Translator for the active language: t('record'), t('stages').listener, t('reviewSpots')(3) */
export const makeT = (lang) => (key) => {
  const v = STRINGS[lang]?.[key];
  return v !== undefined ? v : STRINGS.en[key] ?? key;
};
